inline flight::Array<flight::String> collect_particle_designer_serialize_warnings(flight::StructuralRef<flight::RowReadonly<flight::RowOf<flight::Ref<flight::types::ParticleEmitterConfig>>>> config) {
  flight::Array<flight::String> warnings = flight::Array<flight::String>{};
  if (((flight::row_get<flight::RowKey<"blendMode">>(config).has_value() && (flight::row_get<flight::RowKey<"blendMode">>(config).value() != flight::String("add"))) && (flight::row_get<flight::RowKey<"blendMode">>(config).value() != flight::String("normal")))) {
    warnings.push(flight::String("Blend mode '") + flight::to_string(flight::row_get<flight::RowKey<"blendMode">>(config).value()) + flight::String("' has no Particle Designer equivalent and was approximated as 'normal'"));
  }
  if (flight::row_get<flight::RowKey<"colorCurve">>(config).has_value()) {
    warnings.push(flight::String("Color curve has more than two stops; Particle Designer stores only start and end colors"));
  }
  if (flight::row_get<flight::RowKey<"alphaCurve">>(config).has_value()) {
    warnings.push(flight::String("Alpha curve has more than two stops; Particle Designer stores only start and end alpha"));
  }
  if (flight::row_get<flight::RowKey<"scaleCurve">>(config).has_value()) {
    warnings.push(flight::String("Scale curve has more than two stops; Particle Designer stores only start and end size"));
  }
  if ((flight::row_get<flight::RowKey<"burstCount">>(config) > 0.0)) {
    warnings.push(flight::String("Emission bursts are not supported by the Particle Designer format and were ignored"));
  }
  if ((flight::row_get<flight::RowKey<"velocityInheritance">>(config) != 0.0)) {
    warnings.push(flight::String("velocityInheritance is not supported by the Particle Designer format and was ignored"));
  }
  return warnings;
}

